type Product = {
  id: string;
  name: string;
  pricing: { currency: string; basePrice: number };
  addresses: Array<{
    label: string; line1: string; city: string;
    state: string; postalCode: string; country: string;
  }>;
  variants: Array<{ sku: string; size: string; color: string; price: number; stock: number }>;
};

import { createResource, zodResolver } from 'qortex-resource';

const product = createResource<Product>({
  key: ['product', productId],
  validate: { resolver: zodResolver(ProductSchema), on: 'blur' },
  persist: { draft: true, debounce: 400 },
  mutation: { optimistic: true },
  source: {
    fetch: () => api.getProduct(productId),
    save: (draft) => api.updateProduct(productId, draft),
  },
});

product.array('addresses').append({
  label: 'Warehouse', line1: '', city: '', state: '', postalCode: '', country: 'US',
});

product.set('addresses.0.city', 'Austin');
product.array('variants').move(2, 0);
